package me.timschneeberger.rootlessjamesdsp.fusion

import android.app.Application
import org.junit.Assert.*
import org.junit.Test
import org.junit.runner.RunWith
import org.robolectric.RobolectricTestRunner
import org.robolectric.RuntimeEnvironment
import org.robolectric.annotation.Config

@RunWith(RobolectricTestRunner::class) @Config(sdk=[35],application=Application::class)
class ToneAdvancedParametersTest {
    private val p=ToneAdvancedParameters
    private val app:Application get()=RuntimeEnvironment.getApplication()
    @Test fun defaultsOffAndOriginalIntStringFoundationNeverInitializedByNormalize(){val pref=ToneAdvancedController.preferences(app);pref.edit().clear().putString(p.BASE_RANGE,"40").putInt(p.baseKeys[0],37).putBoolean(p.ENABLED,true).commit();val before=pref.all;p.normalize(pref);assertEquals(before,pref.all);val s=p.capture(pref.all);assertEquals(37,s.base[0]);assertEquals("40",s.baseRange);assertTrue(p.switches.none {p.on(s.values(),it)});assertEquals(49,p.numbers.size);assertEquals(80,p.packet(pref.all).size);assertEquals(1,p.packet(pref.all)[2]);assertFalse(p.keys.contains(p.ENABLED))}
    @Test fun everyFieldRoundTripsAndPacketUsesExactUnits(){val s=p.defaults().copy(base=List(10){13},baseRange="20",professional=true,coreOn=true,delta=List(10){137},amount=1317,shapeOn=true,q=listOf(83,79,89,113,137,173),dynamicOn=true,bassFast=137,bassSlow=317,transientFast=73,transientSlow=137,mixOn=true,mix=317,outputOn=true,output=-29);assertTrue(s.valid());assertEquals(s,p.capture(s.values()));val v=s.packet(true);assertEquals(1,v[1]);assertEquals(1,v[2]);assertEquals(20,v[3]);assertEquals(13,v[4]);assertEquals(137,v[16]);assertEquals(83,v[37]);assertEquals(137,v[54]);assertEquals(317,v[55]);assertEquals(317,v[65]);assertEquals(-29,v[67]);assertTrue((72..79).all {v[it]==0})}
    @Test fun strictFoundationRejectsWrongTypesOutOfRangeAndInvalidRange(){for(v in listOf(mapOf(p.BASE_RANGE to 40),mapOf(p.BASE_RANGE to "21"),mapOf(p.baseKeys[0] to 1f),mapOf(p.baseKeys[0] to "1"),mapOf(p.baseKeys[0] to 101),mapOf(p.BASE_RANGE to "20",p.baseKeys[0] to 21),mapOf(p.ENABLED to 1)))assertFalse(v.toString(),p.validSavedFoundation(v));assertTrue(p.validSavedFoundation(mapOf(p.BASE_RANGE to "20",p.baseKeys[0] to -20)))}
    @Test fun invalidOldBasisIsNotRewrittenAndNewMalformedValuesNormalizeSeparately(){val pref=ToneAdvancedController.preferences(app);pref.edit().clear().putString(p.baseKeys[0],"bad").putString(p.BASE_RANGE,"invalid").putInt(p.amount.key,2001).putString(p.PROFESSIONAL,"true").putInt(p.bassFast.key,500).putInt(p.bassSlow.key,5).commit();p.normalize(pref);assertEquals("bad",pref.getString(p.baseKeys[0],null));assertEquals("invalid",pref.getString(p.BASE_RANGE,null));assertEquals(1000,p.value(pref.all,p.amount));assertFalse(p.enabled(pref.all));assertEquals(50,p.value(pref.all,p.bassFast));assertEquals(70,p.value(pref.all,p.bassSlow));assertFalse(pref.contains(p.output.key))}
    @Test fun fineCorrectionAddsToCurrentBasisAndResetReturnsCurrentBasis(){val s=p.defaults().copy(base=List(10){37},professional=true,coreOn=true,delta=List(10){137});assertEquals(50.7,p.effective(s.values(),0),.0001);assertEquals(37.0,p.effective(s.copy(delta=List(10){0}).values(),0),0.0);assertEquals(100.0,p.effective(s.copy(delta=List(10){1000}).values(),0),0.0);assertEquals(200.0,p.effective(s.copy(delta=List(10){1000},amount=2000).values(),0),0.0);assertEquals(37.0,p.effective(s.copy(professional=false).values(),0),0.0)}
    @Test fun localWindowOnlyExpandsPresentationAndNeverClampsAudioValue(){val before=p.defaults().copy(delta=List(10){1371}).values();for(window in listOf(5,10,20,100)){val range=p.localRange(1371,window);assertTrue(1371 in range);assertTrue(-window*10 in range);assertEquals(before,p.capture(before).values())};assertEquals(-50..50,p.localRange(0,5));assertEquals(-1371..100,p.localRange(-1371,10))}
    @Test fun fastSlowRelationsValidatedEvenWhenGroupsOff(){assertFalse(p.defaults().copy(bassFast=50,bassSlow=5).valid());assertFalse(p.defaults().copy(transientFast=500,transientSlow=45).valid());assertFalse(p.candidateValid(p.defaults().values(),p.bassSlow,5));assertTrue(p.candidateValid(p.defaults().values(),p.bassFast,49));assertFalse(p.candidateValid(p.defaults().values()+mapOf(p.bassSlow.key to 5),p.bassFast,50));assertTrue(p.candidateValid(p.defaults().values()+mapOf(p.bassSlow.key to 5),p.bassFast,49))}
    @Test fun takeoverOnlyCoreAndOffGroupsGreyWithoutLosingValues(){val s=p.defaults().copy(professional=true,shapeOn=true,dynamicOn=true);assertFalse(p.takenOver(s.values()));assertTrue(p.takenOver(s.copy(coreOn=true).values()));assertFalse(p.takenOver(s.copy(coreOn=true,professional=false).values()));assertTrue(p.shapeNumbers.all {p.numberEnabled(it.key,s.values())});assertTrue(p.dynamicNumbers.filterNot {it==p.weakFloor}.all {p.numberEnabled(it.key,s.values())});assertFalse(p.numberEnabled(p.weakFloor.key,s.values()));assertTrue(p.numberEnabled(p.weakFloor.key,s.copy(weakOn=true).values()));assertTrue(p.numbers.none {p.numberEnabled(it.key,s.copy(professional=false).values())})}
    @Test fun numericPrecisionRoundTripAndReferenceDefaultsAreRealDSPUnits(){for(c in p.numbers)for(n in listOf(c.min,c.default,c.max)){assertEquals(c.key,n,c.parse(c.number(n)))};assertEquals(137,p.delta[0].parse("13.7"));assertNull(p.delta[0].parse("13.71"));assertEquals(83,p.q[0].parse("0.83"));assertEquals(317,p.slope[0].parse("0.317"));assertEquals(137,p.bassFast.parse("13.7"));assertEquals(50,p.bassFast.default);assertEquals(70,p.bassSlow.default)}
    @Test fun applyPreservesPowerAndOtherModulesAndAllZeroClearsNewAudioState(){val pref=ToneAdvancedController.preferences(app);pref.edit().clear().putBoolean(p.ENABLED,true).putInt("sentinel",73).commit();val s=p.defaults().copy(base=List(10){13},baseRange="20",professional=true,shapeOn=true,coreOn=true,delta=List(10){137});p.apply(pref,s);assertTrue(p.moduleEnabled(pref.all));assertEquals(73,pref.getInt("sentinel",0));assertEquals(s,p.capture(pref.all));p.resetAll(pref);assertEquals(p.defaults(),p.capture(pref.all));assertTrue(p.moduleEnabled(pref.all));assertEquals(73,pref.getInt("sentinel",0));assertFalse(pref.all.keys.any {it in p.newKeys})}
    private fun runtime()=IntArray(64).apply {this[0]=1;this[1]=2;this[2]=48000;this[14]=100;this[31]=2000;this[35]=50;this[36]=70;this[37]=20;this[38]=45;this[39]=-800}
    @Test fun runtimeAndResponseStrictlyRejectMalformedSizeEpochRangeAndReserved(){assertNotNull(p.decode(runtime()));for((i,n)in listOf(0 to 2,1 to 3,2 to 7999,14 to 21,31 to 1999,35 to 0,36 to 501,63 to 1))assertNull(p.decode(runtime().apply {this[i]=n}));assertNull(p.decode(runtime()+0));val graph=IntArray(200).apply {this[0]=1;this[1]=2;this[2]=48000;this[3]=1;this[4]=32;for(i in 0 until 32){this[8+i*6]=20+i*500;this[9+i*6]=-137;this[10+i*6]=-317;this[13+i*6]=1}};assertNotNull(p.decodeResponse(graph));assertNull(p.decodeResponse(graph.copyOf().apply {this[14]=20}));assertNull(p.decodeResponse(graph.copyOf().apply {this[11]=1}));assertNull(p.decodeResponse(graph.copyOf().apply {this[7]=1}))}
}
